<?php
function report_render_result($r,$basePage='reports'){
 $query=$r['filters'];$query['page']=$basePage;if($basePage==='product_detail')$query['id']=$query['product_id'];$export=$query;unset($export['page']);
 if($r['summary']){echo '<div class="mini-kpis report-summary">';foreach($r['summary'] as $k=>$v)echo '<div><span>'.e($k).'</span><strong>'.e($v).'</strong></div>';echo '</div>';}
 echo '<div class="card"><div class="card-head"><div><h3>'.e($r['title']).'</h3><p>'.e($r['filters']['from'].' — '.$r['filters']['to']).' · '.e(count($r['rows'])).' records</p></div><div class="modal-actions"><a class="btn secondary" href="report.php?'.e(http_build_query($export+['format'=>'xlsx'])).'">Download Excel</a><a class="btn ghost" target="_blank" rel="noopener" href="report.php?'.e(http_build_query($export+['format'=>'print'])).'">Print / Save as PDF</a></div></div>';
 echo '<p class="small muted">Generated '.e($r['generated']).' · '.e($r['user']).' · '.e(json_encode(array_filter($r['filters'],fn($v)=>$v!==''&&$v!==0),JSON_UNESCAPED_UNICODE)).'</p><div class="table-wrap"><table class="table"><thead><tr>';foreach($r['headers'] as $h)echo '<th>'.e($h).'</th>';echo '<th>Source</th></tr></thead><tbody>';$offset=max(0,(int)($_GET['offset']??0));foreach(array_slice($r['rows'],$offset,50,true) as $i=>$row){echo '<tr>';foreach($row as $v)echo '<td>'.e($v).'</td>';echo '<td>'.(!empty($r['links'][$i])?'<a class="btn ghost sm" href="'.e($r['links'][$i]).'">View</a>':'—').'</td></tr>';}if(!$r['rows'])echo '<tr><td colspan="'.(count($r['headers'])+1).'">No matching movements or records. Opening/closing rows are retained where applicable.</td></tr>';echo '</tbody></table></div><div class="modal-actions">';if($offset>0)echo '<a class="btn ghost" href="?'.e(http_build_query($query+['offset'=>max(0,$offset-50)])).'">Previous</a>';if($offset+50<count($r['rows']))echo '<a class="btn ghost" href="?'.e(http_build_query($query+['offset'=>$offset+50])).'">Next</a>';echo '<span class="muted small">50 rows per page · Exports include all matching rows.</span></div>';foreach($r['notes'] as $note)echo '<p class="muted small">'.e($note).'</p>';echo '</div>';
}
